const b=$input.first().json.body||{};
const L=['en','ar','hi','zh','ur','es'].includes(b.lang)?b.lang:'en';
const T={
  en: `Heads up: your balance may drop to £${b.lowest} (below £${b.threshold}) in ${b.inDays} days. Open the app for options.`,
  ar: `تنبيه: قد ينخفض رصيدك إلى £${b.lowest} خلال ${b.inDays} أيام. افتح التطبيق لرؤية الخيارات.`,
  hi: `ध्यान दें: ${b.inDays} दिनों में आपका बैलेंस £${b.lowest} तक गिर सकता है। विकल्पों के लिए ऐप खोलें।`,
  zh: `提醒：${b.inDays}天内你的余额可能降至£${b.lowest}。打开应用查看选项。`,
  ur: `خبردار: ${b.inDays} دن میں آپ کا بیلنس £${b.lowest} تک گر سکتا ہے۔ آپشنز کے لیے ایپ کھولیں۔`,
  es: `Aviso: tu saldo podría bajar a £${b.lowest} en ${b.inDays} días. Abre la app para ver opciones.`
};
const D={"en": "Guidance, not regulated financial advice.", "ar": "إرشاد وليس نصيحة مالية منظمة.", "hi": "मार्गदर्शन, विनियमित वित्तीय सलाह नहीं।", "zh": "仅为指导，非受监管的财务建议。", "ur": "رہنمائی، منظم مالی مشورہ نہیں۔", "es": "Orientación, no asesoramiento financiero regulado."};
return [{json:{message:T[L]+' '+D[L],lang:L}}];
